export function getWordsByPhase(phase: number): Word[] {
  return words.filter((w) => w.phase === phase);
}

export function getWordsBySubPhase(subPhaseKey: string): Word[] {
  return words.filter((w) => w.subPhaseKey === subPhaseKey);
}

export function getWordById(id: string): Word | undefined {
  return words.find((w) => w.id === id);
}
